        "title": "Mars Climate Orbiter Mishap Investigation Board — Phase I Report",
        "url": "https://discovery.larc.nasa.gov/pdf_files/MCO_report_2.pdf",
        "status": "located",
        "checkedAt": "2026-09-29",
